const ajuste = (cantidadContada, extra = {}) => ({ articulo: "A1", almacen: "LPZ", cantidadContada, motivo: "recuento", ...extra });

test("ajuste: recuento menor agrega un egreso por la diferencia", () => {
  const antes = conIngreso();
  const despues = ajustarInventario(antes, ajuste(7));
  assert.equal(antes.length, 1);
  assert.equal(despues.length, 2);
  assert.deepEqual(despues.at(-1), { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 3, motivo: "recuento" });
  assert.equal(stock(despues, "A1", "LPZ"), 7);
  assert.ok(Object.isFrozen(despues));
});

test("ajuste: recuento mayor agrega un ingreso por la diferencia", () => {
  const despues = ajustarInventario(conIngreso(), ajuste(14));
  assert.deepEqual(despues.at(-1), { tipo: "ingreso", articulo: "A1", almacen: "LPZ", cantidad: 4, motivo: "recuento" });
  assert.equal(stock(despues, "A1", "LPZ"), 14);
});

test("ajuste: sin diferencia no agrega nada", () => {
  const antes = conIngreso();
  assert.equal(ajustarInventario(antes, ajuste(10)).length, 1);
});

test("ajuste: recuento en cero deja el stock en cero y sin stock previo cuenta como ingreso", () => {
  assert.equal(stock(ajustarInventario(conIngreso(), ajuste(0)), "A1", "LPZ"), 0);
  assert.equal(stock(ajustarInventario([], ajuste(5)), "A1", "LPZ"), 5);
});

test("ajuste: recuentos inválidos se rechazan", () => {
  for (const c of [-1, 1.5, "7", undefined, NaN]) assert.throws(() => ajustarInventario(conIngreso(), ajuste(c)), RangeError);
  assert.throws(() => ajustarInventario(conIngreso(), ajuste(5, { articulo: "" })));
  assert.throws(() => ajustarInventario(conIngreso(), ajuste(5, { almacen: undefined })));
});
