+// Ajuste por recuento (ADR-001): si lo contado difiere del stock calculado, agrega un movimiento por la
+// diferencia; si no difiere, devuelve la misma lista. Nunca edita movimientos previos.
+export function ajustarInventario(movimientos, { articulo, almacen, cantidadContada, motivo }) {
+  if (!articulo || !almacen) throw new Error("El ajuste necesita artículo y almacén");
+  if (!Number.isInteger(cantidadContada) || cantidadContada < 0)
+    throw new RangeError("La cantidad contada debe ser un entero mayor o igual a 0");
+  const diferencia = cantidadContada - stock(movimientos, articulo, almacen);
+  if (diferencia === 0) return movimientos;
+  return registrarMovimiento(movimientos, {
+    tipo: diferencia > 0 ? "ingreso" : "egreso",
+    articulo,
+    almacen,
+    cantidad: Math.abs(diferencia),
+    motivo,
+  });
+}
